using LinearAlgebra                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                               
 println("=== Julia Matrix Operations ===\n")                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                               
 # 1. Create matrices                                                                                                                                                                                                                                                          
 println("1. Creating matrices:")                                                                                                                                                                                                                                              
 A = [1 2 3; 4 5 6; 7 8 9]                                                                                                                                                                                                                                                     
 B = [9 8 7; 6 5 4; 3 2 1]                                                                                                                                                                                                                                                     
 println("Matrix A:")                                                                                                                                                                                                                                                          
 println(A)                                                                                                                                                                                                                                                                    
 println("\nMatrix B:")                                                                                                                                                                                                                                                        
 println(B)                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                               
 # 2. Element-wise operations                                                                                                                                                                                                                                                  
 println("\n2. Element-wise operations:")                                                                                                                                                                                                                                      
 println("A + B:")                                                                                                                                                                                                                                                             
 println(A + B)                                                                                                                                                                                                                                                                
 println("\nA - B:")                                                                                                                                                                                                                                                           
 println(A - B)                                                                                                                                                                                                                                                                
 println("\nA .* B (element-wise multiplication):")                                                                                                                                                                                                                            
 println(A .* B)                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                               
 # 3. Matrix multiplication                                                                                                                                                                                                                                                    
 println("\n3. Matrix multiplication:")                                                                                                                                                                                                                                        
 println("A * B:")                                                                                                                                                                                                                                                             
 println(A * B)                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                               
 # 4. Transpose                                                                                                                                                                                                                                                                
 println("\n4. Transpose:")                                                                                                                                                                                                                                                    
 println("Transpose of A:")                                                                                                                                                                                                                                                    
 println(A')                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                               
 # 5. Determinant                                                                                                                                                                                                                                                              
 println("\n5. Determinant:")                                                                                                                                                                                                                                                  
 println("det(A) = ", det(A))                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                               
 # 6. Inverse (if invertible)                                                                                                                                                                                                                                                  
 println("\n6. Inverse:")                                                                                                                                                                                                                                                      
 try                                                                                                                                                                                                                                                                           
     A_inv = inv(A)                                                                                                                                                                                                                                                            
     println("Inverse of A:")                                                                                                                                                                                                                                                  
     println(A_inv)                                                                                                                                                                                                                                                            
 catch e                                                                                                                                                                                                                                                                       
     println("Matrix A is not invertible: ", e)                                                                                                                                                                                                                                
 end                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                               
 # 7. Eigenvalues and eigenvectors                                                                                                                                                                                                                                             
 println("\n7. Eigenvalues and eigenvectors:")                                                                                                                                                                                                                                 
 F = eigen(A)                                                                                                                                                                                                                                                                  
 println("Eigenvalues:")                                                                                                                                                                                                                                                       
 println(F.values)                                                                                                                                                                                                                                                             
 println("\nEigenvectors (as columns):")                                                                                                                                                                                                                                       
 println(F.vectors)       